import json
from pathlib import Path


def resolve(root, record):
    digest = record.get("sha256")
    catalog_path = root.joinpath("catalog.json")
    if digest and catalog_path.is_file():
        catalog = json.loads(catalog_path.read_text())
        rows = catalog.get("rows", [])
        for row in rows:
            if row.get("sha256") == digest:
                candidate = row.get("path")
                if candidate:
                    path = root.joinpath(candidate)
                    if path.is_file():
                        return str(path.relative_to(root))

    manifest_path = root.joinpath("manifest.json")
    if digest and manifest_path.is_file():
        manifest = json.loads(manifest_path.read_text())
        rows = manifest.get("rows", [])
        for row in rows:
            if row.get("sha256") == digest:
                candidate = row.get("path")
                if candidate:
                    path = root.joinpath(candidate)
                    if path.is_file():
                        return str(path.relative_to(root))

    raise FileNotFoundError()
